async function cdqLoadPdfRecord(id){
  let rec=await window.cdqEnsurePdf(id,false);

  let pending=null;
  try{
    const queue=await Promise.race([
      cdqV19QueueGet(),
      new Promise(function(resolve){setTimeout(function(){resolve([]);},800);})
    ]);
    pending=(Array.isArray(queue)?queue:[]).find(a=>a.kind==='pdf-import'&&a.targetId===id)||null;
  }catch(_){pending=null;}

  if(pending)rec=Object.assign({},rec,{blob:new Blob([cdqV2112Base64ToBytes(pending.data)],{type:'application/pdf'})});

  // Les gros PDF haute qualité ne sont plus entièrement réécrits avant ouverture.
  if(rec&&rec.blob instanceof Blob&&rec.blob.size<=8*1024*1024){
    rec=await cdqPersonnaliserRecordTechnicienPdf(rec);
  }

  if(!pending){
    Promise.resolve(cdqV19PutRecord('document-pdf',id,rec)).catch(function(){});
  }
  return rec;
}

