async function cdqV2130PreparerCopiePdfImmediatement(resultat,idClient){
  resultat=resultat||{};
  const id=String(resultat.id||"");
  if(!/^[\w-]+$/.test(id))return false;

  const modeleId=cdqModeleIntermediaireId(resultat.modeleId);
  function correspond(rec){
    return !!(rec && rec.revision===CDQ_TEMPLATE_REVISION && rec.blob instanceof Blob && rec.blob.size>0 &&
      rec.templateType===modeleId && rec.blob.size===Number(resultat.taille) &&
      String(rec.templateId)===String(resultat.templateId) &&
      Number(rec.modifieLe)===Number(resultat.templateModifieLe));
  }
  let modele=await cdqV2112GetCachedTemplate(modeleId);
  if(!correspond(modele)){
    if(navigator.onLine)await cdqV2112EnsureTemplateOfflineCached(false,modeleId);
    modele=await cdqV2112GetCachedTemplate(modeleId);
  }
  // Si le maître a changé après la copie, le lecteur chargera le vrai PDF Drive.
  if(!correspond(modele))return false;

  const blobTechnicien=(modele.blob instanceof Blob && modele.blob.size<=8*1024*1024)
    ? await cdqPersonnaliserBlobTechnicienPdf(modele.blob)
    : modele.blob;
  const techKey=String(cdqTechniciensVersion||"cache")+"|"+String(utilisateurCourantEmail||"").toLowerCase()+"|"+String(utilisateurCourantNomRapport||"");
  await cdqV19PutRecord("document-pdf",id,{
    id:id,nom:String(resultat.nom||modele.nom||"Balance intermédiaire.pdf"),clientId:String(resultat.clientId||idClient||compagnieSelectionnee||""),type:"PDF",
    taille:Number(blobTechnicien.size),revision:String(resultat.revision||("copie-locale-"+Date.now())),chunks:Math.ceil(blobTechnicien.size/(1024*1024)),blob:blobTechnicien,
    instantCopy:true,localReadyUntil:Date.now()+(12*60*60*1000),cachedAt:Date.now(),cdqTechVersion:(blobTechnicien===modele.blob?"":techKey)
  });
  return true;
}

window.cdqPreparerCopiePdfImmediatement=cdqV2130PreparerCopiePdfImmediatement;
